arguments.command:
cd /home/runner/work/flutter_agent_harness/flutter_agent_harness && git --no-pager diff origin/main...HEAD --unified=0 | awk '
/^\+\+\+ b\// {f=substr($0,7)}
/^@@ -[0-9]+(,[0-9]+)? \+([0-9]+)(,([0-9]+))? @@/ {start=$3; sub(/,.*/,"",start); n=($4==""?1:substr($4,2)); for(i=0;i<n;i++) added[f][start+i]=1}
/^@/ {next}
/^\+/ {next}
' ; git --no-pager diff origin/main...HEAD --unified=0 | python3 -c "
import sys, re, json
added = {}
f = None
for line in sys.stdin:
    if line.startswith('+++ b/'): f = line[6:].strip()
    elif line.startswith('@@'):
        m = re.match(r'@@ -\d+(?:,\d+)? \+(\d+)(?:,(\d+))? @@', line)
        s = int(m.group(1)); n = int(m.group(2) or 1)
        for i in range(n): added.setdefault(f, set()).add(s+i)
d = json.load(open('outputs/pr_review.json'))
for c in d['inlineComments']:
    ok = c['line'] in added.get(c['path'], set())
    print(f\"{c['path']}:{c['line']} -> {'IN DIFF ✓' if ok else 'NOT IN DIFF ✗'}\")
"

